// Shared helpers for company tender tests (tender-drafts, tender-actions). Not a spec file.
import { expect, Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

/** Fails the test if a payment step/window shows up (free tender must never reach payment). */
export async function expectNoPayment(page: Page) {
  await expect(page, 'payment window must not appear for a free tender').not.toHaveURL(/pay|checkout|payment/i);
  await expect(page.getByRole('dialog', { name: /תשלום/ }), 'payment dialog must not appear').toHaveCount(0);
}

/**
 * «+ פרסום» → «פרסום מכרז» → «מכרז ללא קידום», fills the required fields and stops at step 4 (terms).
 * Never clicks «פרסום המכרז». Returns the tender id from the wizard URL (the draft exists from step 2 on).
 */
export async function fillFreeTenderWizardToTerms(page: Page, title: string, description: string): Promise<string> {
  await page.goto('/tenders?mine=1');
  await page.getByRole('button', { name: '+ פרסום' }).click();
  await page.getByRole('menuitem', { name: /^פרסום מכרז/ }).click();
  await expect(page).toHaveURL(/\/publish\/tender(\?|$)/);
  await expect(page.getByText('שלב 1 מתוך 4')).toBeVisible();

  // Step 1: free tender
  await page.getByRole('radio', { name: /^מכרז ללא קידום/ }).check();
  await page.getByRole('button', { name: 'המשך' }).click();
  await expect(page).toHaveURL(/\/publish\/tender\/visibility\?id=/);
  const id = new URL(page.url()).searchParams.get('id')!;
  await expectNoPayment(page);

  // Step 2: defaults — «מכרז גלוי», «אין צורך ב-NDA» (free)
  await expect(page.getByRole('radio', { name: /^אין צורך ב-NDA/ })).toBeChecked();
  await page.getByRole('button', { name: 'המשך' }).click();
  await expect(page).toHaveURL(/\/publish\/tender\/details\?id=/);

  // Step 3: details
  await page.getByRole('textbox', { name: /^כותרת/ }).fill(title);
  await page.getByRole('textbox', { name: /^תיאור/ }).fill(description);
  await page.getByRole('combobox', { name: /^תעשייה/ }).click();
  await page.getByRole('option', { name: 'בריאות, מדעי החיים וביוטכנולוגיה', exact: true }).click();
  await page.getByRole('combobox', { name: /^אזור משרה/ }).click();
  await page.getByRole('option', { name: 'כל הארץ', exact: true }).click();
  const until = new Date(Date.now() + 30 * 24 * 3600 * 1000);
  await page.getByRole('combobox', { name: 'יום', exact: true }).click();
  await page.getByRole('option', { name: String(until.getDate()), exact: true }).click();
  await page.getByRole('combobox', { name: 'חודש', exact: true }).click();
  await page.getByRole('option', { name: String(until.getMonth() + 1), exact: true }).click();
  await page.getByRole('combobox', { name: 'שנה', exact: true }).click();
  await page.getByRole('option', { name: String(until.getFullYear()), exact: true }).click();
  await page.getByRole('checkbox', { name: 'פרויקטלי', exact: true }).check();
  await page.getByRole('button', { name: 'המשך' }).click();

  // Step 4: terms — stop here
  await expect(page).toHaveURL(new RegExp(`/publish/tender/terms\\?id=${id}`));
  await expect(page.getByText('שלב 4 מתוך 4')).toBeVisible();
  await expectNoPayment(page);
  return id;
}

/** On step 4: tick the three confirmations, sign, click «פרסום המכרז» (free tender only). */
export async function publishFromTerms(page: Page) {
  const boxes = page.getByRole('main').getByRole('checkbox');
  await expect(boxes).toHaveCount(3);
  for (let i = 0; i < 3; i++) await boxes.nth(i).check();
  const pad = page.getByRole('img', { name: /תיבת חתימה/ });
  const box = (await pad.boundingBox())!;
  await page.mouse.move(box.x + 40, box.y + 40);
  await page.mouse.down();
  await page.mouse.move(box.x + 100, box.y + 75, { steps: 5 });
  await page.mouse.move(box.x + 180, box.y + 35, { steps: 5 });
  await page.mouse.up();
  await page.getByRole('button', { name: 'פרסום המכרז' }).click();
  await expect(page).toHaveURL(/\/publish\/tender\/done\?.*free=1/);
  await expectNoPayment(page);
}

/** Records QA-AUTO data that could not be removed by the test (journal for manual cleanup). */
export function journal(line: string) {
  const file = path.join(__dirname, '../../test-data-journal.log');
  fs.appendFileSync(file, `${new Date().toISOString()} company ${line}\n`);
}
